'use strict';
const data=window.RESOURCES;
const $=s=>document.querySelector(s);
const icons={all:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',Architecture:'<path d="m3 9 9-6 9 6M4 21h16M6 9v12M10 9v12M14 9v12M18 9v12M3 9h18"/>',Archives:'<rect x="4" y="4" width="16" height="5" rx="1"/><path d="M5 9v12h14V9M9 13h6"/>',Cinéma:'<rect x="3" y="8" width="18" height="13" rx="2"/><path d="M3 8V4h18v4M7 4l3 4m3-4 3 4M7 12h5"/>','Enseignement Recherche':'<path d="m2 8 10-5 10 5-10 5zM6 10v7c4 3 8 3 12 0v-7M22 8v9"/>',"Histoire de l'art":'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="m7 17 4-6 3 4 3-2 1 4M8 7h.01"/>','Langue française':'<path d="M21 12a8 8 0 0 1-8 8H8l-5 2 2-5a8 8 0 1 1 16-5Z"/><path d="m8 14 3-7 3 7M9 12h4"/>','Livre et Lecture':'<path d="M3 4h6c3 0 3 2 3 2s0-2 3-2h6v16h-6c-3 0-3 2-3 2s0-2-3-2H3zM12 6v16"/>',Musées:'<path d="m2 8 10-5 10 5H2M3 21h18M5 11v7M10 11v7M15 11v7M20 11v7"/>',Musique:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="17" cy="16" rx="3" ry="3"/>','Patrimoine immatériel':'<path d="M7 3h10v18H7zM3 7h4m10 0h4M3 17h4m10 0h4M10 7h4m-4 5h4m-4 5h4"/>',Photographie:'<path d="M3 7h5l2-3h4l2 3h5v14H3z"/><circle cx="12" cy="13" r="4"/>','Spectacle vivant':'<path d="M3 4c5 3 9 3 18 0v9c0 5-6 8-9 9-3-1-9-4-9-9zM7 10h1m8 0h1M8 15c3 2 5 2 8 0"/>'};
const palettes={Architecture:['#856950','#f5eee8'],Archives:['#84634f','#f4ece5'],Cinéma:['#866d8b','#f1edf4'],'Enseignement Recherche':['#567a8c','#ebf2f5'],"Histoire de l'art":['#7e6e91','#f0edf5'],'Langue française':['#9b8350','#f7f2e6'],'Livre et Lecture':['#6f7e58','#f0f3e9'],Musées:['#7d8065','#f0f1e9'],Musique:['#8c715b','#f5eee7'],'Patrimoine immatériel':['#517a74','#eaf3ef'],Photographie:['#7c748d','#f0edf4'],'Spectacle vivant':['#6f8890','#edf3f5']};
const categoryOrder=['Archives','Architecture','Cinéma','Enseignement Recherche',"Histoire de l'art",'Langue française','Livre et Lecture','Musées','Musique','Patrimoine immatériel','Photographie','Spectacle vivant'];
const labels={'Enseignement Recherche':'Enseignement et recherche','Livre et Lecture':'Livre et lecture'};
const state={category:'all',query:'',availability:'all',sort:'az',view:'grid'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr').replace(/[’‘]/g,"'");
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>';
const icon=cat=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[cat]||icons.all)+'</svg>';
function paintCategory(){
 $('#categories').innerHTML=[['all','Toutes les ressources'],...categoryOrder.map(c=>[c,labels[c]||c])].map(([c,label],i)=>`${i===1?'<div class="cat-separator"></div>':''}<button type="button" class="category ${state.category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${state.category===c}">${icon(c)}<span class="cat-name">${esc(label)}</span><span class="count">${c==='all'?data.length:data.filter(r=>r.categories.includes(c)).length}</span></button>`).join('');
 $('#categories').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;render();closeFilters();}));
}
function shortTitle(r){return r.title.split(/\s*:\s*/)[0]}
function syncUrl(){const p=new URLSearchParams();if(state.category!=='all')p.set('domaine',state.category);if(state.query)p.set('q',state.query);if(state.availability!=='all')p.set('liens',state.availability);if(state.sort!=='az')p.set('tri',state.sort);if(state.view!=='grid')p.set('vue',state.view);history.replaceState(null,'',location.pathname+(p.toString()?'?'+p:'')+location.hash);}
function render(){
 paintCategory();const words=norm(state.query).trim().split(/\s+/).filter(Boolean);
 const filtered=data.filter(r=>(state.category==='all'||r.categories.includes(state.category))&&(state.availability==='all'||(state.availability==='current'?r.currentUrl:!r.currentUrl))&&words.every(w=>norm([r.title,r.description,r.organism,...r.categories].join(' ')).includes(w))).sort((a,b)=>a.title.localeCompare(b.title,'fr')*(state.sort==='za'?-1:1));
 $('#sectionTitle').textContent=state.category==='all'?'Toutes les ressources':labels[state.category]||state.category;
 $('#resultCount').textContent=`${filtered.length} ressource${filtered.length>1?'s':''} ${filtered.length>1?'affichées':'affichée'} sur ${data.length}`;
 $('#results').className='cards'+(state.view==='list'?' list':'');$('#empty').hidden=filtered.length>0;
 const filteredActive=state.category!=='all'||state.query||state.availability!=='all';$('#reset').hidden=!filteredActive;
 const active=[];if(state.category!=='all')active.push(['category',labels[state.category]||state.category]);if(state.query)active.push(['query','« '+state.query+' »']);if(state.availability!=='all')active.push(['availability',state.availability==='current'?'Adresse actuelle disponible':'Adresse à retrouver']);
 $('#activeFilters').innerHTML=active.map(([k,v])=>`<button class="filter-chip" data-clear="${k}" aria-label="Retirer le filtre ${esc(v)}">${esc(v)}<span aria-hidden="true">×</span></button>`).join('');
 $('#activeFilters').querySelectorAll('button').forEach(b=>b.onclick=()=>{state[b.dataset.clear]=b.dataset.clear==='query'?'':'all';$('#search').value=state.query;$('#availability').value=state.availability;render()});
 $('#results').innerHTML=filtered.map(r=>{const c=state.category==='all'?r.categories[0]:state.category;const [accent,tint]=palettes[c];return `<article class="card" style="--accent:${accent};--tint:${tint}"><div class="card-top"><span class="resource-icon">${icon(c)}</span><span class="domain">${esc(labels[c]||c)}${r.categories.length>1?'<span class="more-cats" title="Plusieurs catégories">+'+(r.categories.length-1)+'</span>':''}</span></div><h3><button class="title-button" data-resource="${r.id}" aria-label="Voir la fiche de ${esc(r.title)}">${esc(shortTitle(r))}</button></h3><p class="description">${esc(r.description)}</p><div class="card-bottom"><span class="link-status ${r.currentUrl?'':'review'}">${r.currentUrl?'Adresse actuelle':'Lien à actualiser'}</span>${r.currentUrl?`<a class="card-link" href="${esc(r.currentUrl)}" target="_blank" rel="noopener noreferrer" aria-label="Consulter ${esc(shortTitle(r))} (nouvel onglet)">Consulter ${arrow}</a>`:`<button class="card-link" data-resource="${r.id}">Voir la fiche <span aria-hidden="true">→</span></button>`}</div></article>`}).join('');
 $('#results').querySelectorAll('[data-resource]').forEach(b=>b.addEventListener('click',()=>openResource(b.dataset.resource)));
 $('#gridView').setAttribute('aria-pressed',state.view==='grid');$('#listView').setAttribute('aria-pressed',state.view==='list');syncUrl();
}
function openResource(id){const r=data.find(r=>r.id===id);if(!r)return;const [accent,tint]=palettes[r.categories[0]];
 $('#dialogContent').innerHTML=`<div class="dialog-categories" style="--accent:${accent};--tint:${tint}">${r.categories.map(c=>'<span class="badge">'+esc(labels[c]||c)+'</span>').join('')}</div><h2 id="dialogTitle" class="detail-title">${esc(r.title)}</h2><span class="detail-label">DESCRIPTION ORIGINALE · GENIALLY MPDOC</span><p class="detail-description">${esc(r.description)}</p><div class="detail-organism"><strong>ORGANISME MENTIONNÉ DANS LA SOURCE</strong>${esc(r.organism)}</div>${r.currentUrl?`<a class="detail-action" href="${esc(r.currentUrl)}" target="_blank" rel="noopener noreferrer">Consulter l’adresse actuelle ${arrow}</a><p class="detail-note">Notice ou portail consulté le 28 octobre 2026. La disponibilité de cette page ne garantit pas celle de toutes les fonctions du service associé.</p>`:`<div class="detail-no-url"><strong>Une adresse actuelle reste à retrouver.</strong><br>Le lien d’origine retournait une erreur 404 au dernier contrôle. Cela ne signifie pas que la ressource a disparu.</div>`}${r.serviceUrl?`<div class="detail-service"><a href="${esc(r.serviceUrl)}" target="_blank" rel="noopener noreferrer">Accéder au service indiqué par la notice ↗</a><p>Lien repéré dans la notice institutionnelle actuelle. Son fonctionnement n’a pas été vérifié dans cet inventaire.</p></div>`:''}<div class="detail-comparison"><strong>Comparaison avec la liste officielle</strong>${esc(r.comparison)}<br>${esc(r.comparisonNote)}</div><details class="original"><summary>Traçabilité, lien d’origine et observations</summary><div class="original-content"><strong>${esc(r.occurrences.join(' · '))}</strong> · Source : Genially, page 1/1.<p>${esc(r.location)}</p><strong>Ancienne adresse — erreur 404 constatée</strong><br><a href="${esc(r.originalUrl)}" target="_blank" rel="noopener noreferrer">${esc(r.originalUrl)}</a><p>${esc(r.observations)}</p><strong>Type d’accès indiqué : ${esc(r.access)}</strong></div></details>`;
 $('#resourceDialog').showModal();$('#resourceDialog').scrollTop=0;
}
function reset(){state.category='all';state.query='';state.availability='all';$('#search').value='';$('#availability').value='all';render()}
function closeFilters(){$('.sidebar').classList.remove('open');$('.sidebar').inert=window.matchMedia('(max-width:680px)').matches;$('#filterBackdrop').hidden=true;$('#mobileFilters').setAttribute('aria-expanded','false')}
$('#search').addEventListener('input',e=>{state.query=e.target.value;render()});$('#availability').addEventListener('change',e=>{state.availability=e.target.value;render()});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;render()});$('#reset').onclick=reset;$('#emptyReset').onclick=reset;
$('#gridView').onclick=()=>{state.view='grid';render()};$('#listView').onclick=()=>{state.view='list';render()};
for(const b of document.querySelectorAll('.close-dialog'))b.onclick=()=>b.closest('dialog').close();
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close()}});
$('#aboutButton').onclick=$('#methodButton').onclick=()=>$('#aboutDialog').showModal();
$('#mobileFilters').onclick=()=>{$('.sidebar').inert=false;$('.sidebar').classList.add('open');$('#filterBackdrop').hidden=false;$('#mobileFilters').setAttribute('aria-expanded','true');$('#closeFilters').focus()};$('#closeFilters').onclick=()=>{closeFilters();$('#mobileFilters').focus()};$('#filterBackdrop').onclick=closeFilters;
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeFilters();if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
window.matchMedia('(max-width:680px)').addEventListener('change',closeFilters);closeFilters();
const params=new URLSearchParams(location.search);if(categoryOrder.includes(params.get('domaine')))state.category=params.get('domaine');state.query=params.get('q')||'';if(['current','review'].includes(params.get('liens')))state.availability=params.get('liens');if(params.get('tri')==='za')state.sort='za';if(params.get('vue')==='list')state.view='list';$('#search').value=state.query;$('#availability').value=state.availability;$('#sort').value=state.sort;render();
